mapper.select:
select  from marketing_channel_order_verification
where account_id = #{accountId}
and status = #{status}
and create_time >= #{from}
and create_time < #{to}
order by id desc limit #{limit}

mapper.update:
update marketing_channel_order_verification
set status = 2, reason_code = #{reasonCode}, raw_hash = #{rawHash}, update_time = #{updateTime}
where id = #{id} and status in (0, 2)

update marketing_channel_order_verification
set status = 3, reason_code = #{reasonCode}, update_time = #{updateTime}
where id = #{id} and status in (1, 2)

mapper.select:
select
    coalesce(sum(case when status = 1 then 1 else 0 end), 0) as verifiedOrderCount,
    coalesce(sum(case when status = 1 then amount else 0 end), 0) as verifiedAmount,
    coalesce(sum(case when status = 0 then 1 else 0 end), 0) as pendingVerificationCount
from marketing_channel_order_verification
where account_id = #{accountId}
and create_time >= #{from}
and create_time < #{to}
